async function addInfrastructureToCompany(companyId, entity) {
  try {
    const response = await fetch('/api/vector-memory', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'addCompanyInfrastructure',
        companyId: companyId,
        entity: entity
      })
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const result = await response.json();

    if (!result.success) {
      throw new Error(result.error || 'Failed to add infrastructure entity');
    }

    return {
      success: true,
      entityId: result.entityId,
      companyId: companyId,
      entityName: entity.name,
      entityType: entity.type,
      message: `Added ${entity.type} '${entity.name}' to company ${companyId}`,
      timestamp: new Date().toISOString()
    };
  } catch (error) {
    return {
      success: false,
      error: error.message,
      timestamp: new Date().toISOString()
    };
  }
}
